/**
 * Facial rehabilitation content library.
 *
 * Content follows commonly published facial neuromuscular-retraining
 * principles (gentle, slow, small, symmetric movements with mirror feedback;
 * no maximal-effort or mass movements; stretching/massage and dissociation
 * for synkinesis). It is generic educational content and must be reviewed by
 * a licensed clinician (physiatrist / facial therapist) before clinical use.
 */
import type { MovementTaskId } from '../core';
import { STRETCHES } from './stretches';

export type Region = 'forehead' | 'eye' | 'midface' | 'mouth' | 'neck' | 'whole';
export type Phase = 'acute' | 'recovery' | 'synkinesis';
export type Kind = 'massage' | 'stretch' | 'nmr' | 'dissociation' | 'relax' | 'eyecare';

export interface Exercise {
  id: string;
  title: string;
  kind: Kind;
  regions: Region[];
  phases: Phase[];
  /** Target duration in seconds (timer), or reps for movement exercises. */
  durationSec: number;
  reps?: number;
  holdSec?: number;
  summary: string;
  steps: string[];
  cautions: string[];
  /** Live biofeedback uses this assessment task's measure, if set. */
  biofeedback?: MovementTaskId;
  /** Source the technique was reconstructed from (therapist review required). */
  reference?: string;
}

