const HALLYM: Exercise[] = STRETCHES.map((p) => {
  const m = HALLYM_META[p.id]!;
  const reps = m.reps ?? 2;
  const holdSec = m.holdSec ?? 10;
  const single = p.steps[0]!;
  return {
    id: p.id,
    title: m.title,
    kind: 'stretch' as const,
    regions: m.regions,
    phases: ['recovery', 'synkinesis'] as Phase[],
    durationSec: Math.round(p.steps.length * reps * (6.5 + holdSec + 5.5)),
    reps,
    holdSec,
    summary: m.summary,
    steps:
      p.steps.length > 1
        ? p.steps.map((s) => `${s.title} — ${s.cue}`)
        : [single.cue, `${single.title}.`, `늘린 채 ${holdSec}초 유지합니다.`, '천천히 풀고 숨을 내쉽니다.'],
    cautions: m.cautions,
    reference: HALLYM_REF,
  };
});

export const EXERCISES: readonly Exercise[] = [...BASE, ...HALLYM];

export const exerciseById = (id: string): Exercise | undefined => EXERCISES.find((e) => e.id === id);
